window.docContents[6].resolve({"/Hoare/#Hoare-Logic--Hoare___-Hoare-Logic___-Part-I--Proof-Rules":{"contents":"\n\nWe want to be able to prove Hoare triples formally.Here's our plan:* introduce one \"proof rule\" for each Imp syntactic form* plus a couple of \"structural rules\" that help glue proofs\n    together* prove these rules correct in terms of the definition of\n    ValidHoareTriple* prove programs correct using these proof rules, without ever\n    unfolding the definition of ValidHoareTriple\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Hoare Logic\u0009Hoare: Hoare Logic, Part I","header":"4.4. Proof Rules","id":"/Hoare/#Hoare-Logic--Hoare___-Hoare-Logic___-Part-I--Proof-Rules"}});